UNION ALL SELECT 'OC-1005', 'Featherlite Down Jacket', 'Fjellvik', (SELECT id FROM categories WHERE slug = 'outdoor-clothing'), '800-fill-power goose down in a 20-denier shell packs into its own pocket. A cosy mid layer for belay stops and evenings at camp.', '{"Fill power":"800","Fill weight":"120 g","Packed size":"Fist-sized"}', 198.99, 0
